import React,{useState} from 'https://esm.sh/react@18.3.1';
import{createRoot}from'https://esm.sh/react-dom@18.3.1/client';
import{animated,useSpring}from'https://esm.sh/@react-spring/web@9.7.5';
const e=React.createElement;
function Impact(){const items=[['Wildlife','Recovery needs space, diagnosis, appropriate care and a credible route to release.'],['People','Environmental learning works when people can connect knowledge to places, livelihoods and decisions.'],['Systems','Field priorities travel further when they can reach institutions, finance and policy processes.']];const[i,setI]=useState(0);const style=useSpring({opacity:1,transform:'translateY(0px)',from:{opacity:0,transform:'translateY(12px)'},reset:true,config:{tension:210,friction:24},key:i});return e('div',{className:'impact-island'},e('div',{className:'chip-row'},items.map((x,n)=>e('button',{key:x[0],onClick:()=>setI(n),className:'chip '+(n===i?'is-active':'')},x[0]))),e(animated.div,{style,className:'impact-panel'},e('strong',null,items[i][0]),e('p',null,items[i][1])))}
const root=document.getElementById('impact-island');if(root)createRoot(root).render(e(Impact));
function EngagementFacts(){const style=useSpring({from:{opacity:0,transform:'translateY(18px)'},to:{opacity:1,transform:'translateY(0px)'},delay:420,config:{tension:170,friction:22}});return e(animated.div,{style,className:'engagement-facts','aria-label':'Global engagement overview'},e('span',null,e('strong',null,'06'),' conferences'),e('span',null,e('strong',null,'03'),' accreditations'),e('span',null,e('strong',null,'2023—26'),' timeline'))}
const engagementRoot=document.getElementById('engagement-island');if(engagementRoot)createRoot(engagementRoot).render(e(EngagementFacts));
